type BaseParserType<'input, I> =
	BaseParser<'input,PlSqlParserExt<'input>, I, PlSqlParserContextType , dyn PlSqlParserListener<'input> + 'input >;

type TokenType<'input> = <LocalTokenFactory<'input> as TokenFactory<'input>>::Tok;
pub type LocalTokenFactory<'input> = CommonTokenFactory;

pub type PlSqlParserTreeWalker<'input,'a> =
	ParseTreeWalker<'input, 'a, PlSqlParserContextType , dyn PlSqlParserListener<'input> + 'a>;

/// Parser for PlSqlParser grammar
pub struct PlSqlParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	base:BaseParserType<'input,I>,
	interpreter:Arc<ParserATNSimulator>,
	_shared_context_cache: Box<PredictionContextCache>,
    pub err_handler: Box<dyn ErrorStrategy<'input,BaseParserType<'input,I> > >,
}

impl<'input, I> PlSqlParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
    pub fn set_error_strategy(&mut self, strategy: Box<dyn ErrorStrategy<'input,BaseParserType<'input,I> > >) {
        self.err_handler = strategy
    }

    pub fn with_strategy(input: I, strategy: Box<dyn ErrorStrategy<'input,BaseParserType<'input,I> > >) -> Self {
		antlr4rust::recognizer::check_version("0","5");
		let interpreter = Arc::new(ParserATNSimulator::new(
			_ATN.clone(),
			_decision_to_DFA.clone(),
			_shared_context_cache.clone(),
		));
		Self {
			base: BaseParser::new_base_parser(
				input,
				Arc::clone(&interpreter),
				PlSqlParserExt{
					_pd: Default::default(),
				}
			),
			interpreter,
            _shared_context_cache: Box::new(PredictionContextCache::new()),
            err_handler: strategy,
        }
    }

}

type DynStrategy<'input,I> = Box<dyn ErrorStrategy<'input,BaseParserType<'input,I>> + 'input>;

impl<'input, I> PlSqlParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
    pub fn with_dyn_strategy(input: I) -> Self{
    	Self::with_strategy(input,Box::new(DefaultErrorStrategy::new()))
    }
}

impl<'input, I> PlSqlParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
    pub fn new(input: I) -> Self{
    	Self::with_strategy(input,Box::new(DefaultErrorStrategy::new()))
    }
}

/// Trait for monomorphized trait object that corresponds to the nodes of parse tree generated for PlSqlParser
pub trait PlSqlParserContext<'input>:
	for<'x> Listenable<dyn PlSqlParserListener<'input> + 'x > + 
	ParserRuleContext<'input, TF=LocalTokenFactory<'input>, Ctx=PlSqlParserContextType>
{}

antlr4rust::coerce_from!{ 'input : PlSqlParserContext<'input> }

impl<'input> PlSqlParserContext<'input> for TerminalNode<'input,PlSqlParserContextType> {}
impl<'input> PlSqlParserContext<'input> for ErrorNode<'input,PlSqlParserContextType> {}

antlr4rust::tid! { impl<'input> TidAble<'input> for dyn PlSqlParserContext<'input> + 'input }

antlr4rust::tid! { impl<'input> TidAble<'input> for dyn PlSqlParserListener<'input> + 'input }

pub struct PlSqlParserContextType;
antlr4rust::tid!{PlSqlParserContextType}

impl<'input> ParserNodeType<'input> for PlSqlParserContextType{
	type TF = LocalTokenFactory<'input>;
	type Type = dyn PlSqlParserContext<'input> + 'input;
}

impl<'input, I> Deref for PlSqlParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
    type Target = BaseParserType<'input,I>;

    fn deref(&self) -> &Self::Target {
        &self.base
    }
}

impl<'input, I> DerefMut for PlSqlParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.base
    }
}

pub struct PlSqlParserExt<'input>{
	_pd: PhantomData<&'input str>,
}

impl<'input> PlSqlParserExt<'input>{
}
antlr4rust::tid! { PlSqlParserExt<'a> }

impl<'input> TokenAware<'input> for PlSqlParserExt<'input>{
	type TF = LocalTokenFactory<'input>;
}

impl<'input,I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>> ParserRecog<'input, BaseParserType<'input,I>> for PlSqlParserExt<'input>{}

impl<'input,I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>> Actions<'input, BaseParserType<'input,I>> for PlSqlParserExt<'input>{
	fn get_grammar_file_name(&self) -> & str{ "PlSqlParser.g4"}

   	fn get_rule_names(&self) -> &[& str] {&ruleNames}

   	fn get_vocabulary(&self) -> &dyn Vocabulary { &**VOCABULARY }
	fn sempred(_localctx: Option<&(dyn PlSqlParserContext<'input> + 'input)>, rule_index: i32, pred_index: i32,
			   recog:&mut BaseParserType<'input,I>
	)->bool{
		match rule_index {
					358 => PlSqlParser::<'input,I>::unified_auditing_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					361 => PlSqlParser::<'input,I>::audit_direct_path_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					362 => PlSqlParser::<'input,I>::audit_container_clause_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					368 => PlSqlParser::<'input,I>::auditing_on_clause_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					372 => PlSqlParser::<'input,I>::sql_statement_shortcut_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					404 => PlSqlParser::<'input,I>::library_editionable_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					405 => PlSqlParser::<'input,I>::library_debug_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					417 => PlSqlParser::<'input,I>::alter_view_editionable_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					623 => PlSqlParser::<'input,I>::external_table_condition_clause_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					692 => PlSqlParser::<'input,I>::partial_database_recovery_10g_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					830 => PlSqlParser::<'input,I>::period_definition_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					955 => PlSqlParser::<'input,I>::table_ref_aux_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1030 => PlSqlParser::<'input,I>::dml_table_expression_clause_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1039 => PlSqlParser::<'input,I>::logical_expression_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1043 => PlSqlParser::<'input,I>::multiset_expression_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1044 => PlSqlParser::<'input,I>::relational_expression_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1049 => PlSqlParser::<'input,I>::concatenation_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1055 => PlSqlParser::<'input,I>::unary_expression_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1071 => PlSqlParser::<'input,I>::standard_function_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1107 => PlSqlParser::<'input,I>::string_delimiter_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					1188 => PlSqlParser::<'input,I>::general_element_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
			_ => true
		}
	}
}

