impl<'input> PlSqlParserContext<'input> for Constructor_declarationContext<'input>{}

impl<'input,'a> Listenable<dyn PlSqlParserListener<'input> + 'a> for Constructor_declarationContext<'input>{
		fn enter(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_constructor_declaration(self);
			Ok(())
		}fn exit(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_constructor_declaration(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input> CustomRuleContext<'input> for Constructor_declarationContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = PlSqlParserContextType;
	fn get_rule_index(&self) -> usize { RULE_constructor_declaration }
	//fn type_rule_index() -> usize where Self: Sized { RULE_constructor_declaration }
}
