pub type Dim_refContextAll<'input> = Dim_refContext<'input>;


pub type Dim_refContext<'input> = BaseParserRuleContext<'input,Dim_refContextExt<'input>>;

#[derive(Clone)]
pub struct Dim_refContextExt<'input>{
	pub ad: Option<Rc<Id_expressionContextAll<'input>>>,
	pub da: Option<Rc<Id_expressionContextAll<'input>>>,
ph:PhantomData<&'input str>
}

impl<'input> PlSqlParserContext<'input> for Dim_refContext<'input>{}

impl<'input,'a> Listenable<dyn PlSqlParserListener<'input> + 'a> for Dim_refContext<'input>{
		fn enter(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_dim_ref(self);
			Ok(())
		}fn exit(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_dim_ref(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input> CustomRuleContext<'input> for Dim_refContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = PlSqlParserContextType;
	fn get_rule_index(&self) -> usize { RULE_dim_ref }
	//fn type_rule_index() -> usize where Self: Sized { RULE_dim_ref }
}
antlr4rust::tid!{Dim_refContextExt<'a>}

impl<'input> Dim_refContextExt<'input>{
	fn new(parent: Option<Rc<dyn PlSqlParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<Dim_refContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,Dim_refContextExt{
				ad: None, da: None, 

				ph:PhantomData
			}),
		)
	}
}

pub trait Dim_refContextAttrs<'input>: PlSqlParserContext<'input> + BorrowMut<Dim_refContextExt<'input>>{

fn id_expression_all(&self) ->  Vec<Rc<Id_expressionContextAll<'input>>> where Self:Sized{
	self.children_of_type()
}
fn id_expression(&self, i: usize) -> Option<Rc<Id_expressionContextAll<'input>>> where Self:Sized{
	self.child_of_type(i)
}
fn schema_name(&self) -> Option<Rc<Schema_nameContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}
/// Retrieves first TerminalNode corresponding to token PERIOD
/// Returns `None` if there is no child corresponding to token PERIOD
fn PERIOD(&self) -> Option<Rc<TerminalNode<'input,PlSqlParserContextType>>> where Self:Sized{
	self.get_token(PlSqlParser_PERIOD, 0)
}
/// Retrieves first TerminalNode corresponding to token AS
/// Returns `None` if there is no child corresponding to token AS
fn AS(&self) -> Option<Rc<TerminalNode<'input,PlSqlParserContextType>>> where Self:Sized{
	self.get_token(PlSqlParser_AS, 0)
}

}

