pub type Key_clauseContextAll<'input> = Key_clauseContext<'input>;


pub type Key_clauseContext<'input> = BaseParserRuleContext<'input,Key_clauseContextExt<'input>>;

#[derive(Clone)]
pub struct Key_clauseContextExt<'input>{
	pub a: Option<Rc<Id_expressionContextAll<'input>>>,
ph:PhantomData<&'input str>
}

impl<'input> PlSqlParserContext<'input> for Key_clauseContext<'input>{}

impl<'input,'a> Listenable<dyn PlSqlParserListener<'input> + 'a> for Key_clauseContext<'input>{
		fn enter(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_key_clause(self);
			Ok(())
		}fn exit(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_key_clause(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input> CustomRuleContext<'input> for Key_clauseContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = PlSqlParserContextType;
	fn get_rule_index(&self) -> usize { RULE_key_clause }
	//fn type_rule_index() -> usize where Self: Sized { RULE_key_clause }
}
antlr4rust::tid!{Key_clauseContextExt<'a>}

impl<'input> Key_clauseContextExt<'input>{
	fn new(parent: Option<Rc<dyn PlSqlParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<Key_clauseContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,Key_clauseContextExt{
				a: None, 

				ph:PhantomData
			}),
		)
	}
}

pub trait Key_clauseContextAttrs<'input>: PlSqlParserContext<'input> + BorrowMut<Key_clauseContextExt<'input>>{

/// Retrieves first TerminalNode corresponding to token KEY
/// Returns `None` if there is no child corresponding to token KEY
fn KEY(&self) -> Option<Rc<TerminalNode<'input,PlSqlParserContextType>>> where Self:Sized{
	self.get_token(PlSqlParser_KEY, 0)
}
/// Retrieves first TerminalNode corresponding to token LEFT_PAREN
/// Returns `None` if there is no child corresponding to token LEFT_PAREN
fn LEFT_PAREN(&self) -> Option<Rc<TerminalNode<'input,PlSqlParserContextType>>> where Self:Sized{
	self.get_token(PlSqlParser_LEFT_PAREN, 0)
}
fn id_expression_all(&self) ->  Vec<Rc<Id_expressionContextAll<'input>>> where Self:Sized{
	self.children_of_type()
}
fn id_expression(&self, i: usize) -> Option<Rc<Id_expressionContextAll<'input>>> where Self:Sized{
	self.child_of_type(i)
}
/// Retrieves first TerminalNode corresponding to token RIGHT_PAREN
/// Returns `None` if there is no child corresponding to token RIGHT_PAREN
fn RIGHT_PAREN(&self) -> Option<Rc<TerminalNode<'input,PlSqlParserContextType>>> where Self:Sized{
	self.get_token(PlSqlParser_RIGHT_PAREN, 0)
}
/// Retrieves all `TerminalNode`s corresponding to token COMMA in current rule
fn COMMA_all(&self) -> Vec<Rc<TerminalNode<'input,PlSqlParserContextType>>>  where Self:Sized{
	self.children_of_type()
}
/// Retrieves 'i's TerminalNode corresponding to token COMMA, starting from 0.
/// Returns `None` if number of children corresponding to token COMMA is less or equal than `i`.
fn COMMA(&self, i: usize) -> Option<Rc<TerminalNode<'input,PlSqlParserContextType>>> where Self:Sized{
	self.get_token(PlSqlParser_COMMA, i)
}

}

