pub type Create_mv_refreshContextAll<'input> = Create_mv_refreshContext<'input>;


pub type Create_mv_refreshContext<'input> = BaseParserRuleContext<'input,Create_mv_refreshContextExt<'input>>;

#[derive(Clone)]
pub struct Create_mv_refreshContextExt<'input>{
	pub rb_segment: Option<TokenType<'input>>,
ph:PhantomData<&'input str>
}

impl<'input> PlSqlParserContext<'input> for Create_mv_refreshContext<'input>{}

impl<'input,'a> Listenable<dyn PlSqlParserListener<'input> + 'a> for Create_mv_refreshContext<'input>{
		fn enter(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_create_mv_refresh(self);
			Ok(())
		}fn exit(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_create_mv_refresh(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input> CustomRuleContext<'input> for Create_mv_refreshContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = PlSqlParserContextType;
	fn get_rule_index(&self) -> usize { RULE_create_mv_refresh }
	//fn type_rule_index() -> usize where Self: Sized { RULE_create_mv_refresh }
}
antlr4rust::tid!{Create_mv_refreshContextExt<'a>}

impl<'input> Create_mv_refreshContextExt<'input>{
	fn new(parent: Option<Rc<dyn PlSqlParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<Create_mv_refreshContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,Create_mv_refreshContextExt{
				rb_segment: None, 

				ph:PhantomData
			}),
		)
	}
}

