pub type Commit_statementContextAll<'input> = Commit_statementContext<'input>;


pub type Commit_statementContext<'input> = BaseParserRuleContext<'input,Commit_statementContextExt<'input>>;

#[derive(Clone)]
pub struct Commit_statementContextExt<'input>{
ph:PhantomData<&'input str>
}

impl<'input> PlSqlParserContext<'input> for Commit_statementContext<'input>{}

impl<'input,'a> Listenable<dyn PlSqlParserListener<'input> + 'a> for Commit_statementContext<'input>{
		fn enter(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_commit_statement(self);
			Ok(())
		}fn exit(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_commit_statement(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input> CustomRuleContext<'input> for Commit_statementContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = PlSqlParserContextType;
	fn get_rule_index(&self) -> usize { RULE_commit_statement }
	//fn type_rule_index() -> usize where Self: Sized { RULE_commit_statement }
}
antlr4rust::tid!{Commit_statementContextExt<'a>}

impl<'input> Commit_statementContextExt<'input>{
	fn new(parent: Option<Rc<dyn PlSqlParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<Commit_statementContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,Commit_statementContextExt{

				ph:PhantomData
			}),
		)
	}
}

