pub type Link_nameContextAll<'input> = Link_nameContext<'input>;


pub type Link_nameContext<'input> = BaseParserRuleContext<'input,Link_nameContextExt<'input>>;

#[derive(Clone)]
pub struct Link_nameContextExt<'input>{
ph:PhantomData<&'input str>
}

impl<'input> PlSqlParserContext<'input> for Link_nameContext<'input>{}

impl<'input,'a> Listenable<dyn PlSqlParserListener<'input> + 'a> for Link_nameContext<'input>{
		fn enter(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_link_name(self);
			Ok(())
		}fn exit(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_link_name(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input> CustomRuleContext<'input> for Link_nameContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = PlSqlParserContextType;
	fn get_rule_index(&self) -> usize { RULE_link_name }
	//fn type_rule_index() -> usize where Self: Sized { RULE_link_name }
}
antlr4rust::tid!{Link_nameContextExt<'a>}

impl<'input> Link_nameContextExt<'input>{
	fn new(parent: Option<Rc<dyn PlSqlParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<Link_nameContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,Link_nameContextExt{

				ph:PhantomData
			}),
		)
	}
}

pub trait Link_nameContextAttrs<'input>: PlSqlParserContext<'input> + BorrowMut<Link_nameContextExt<'input>>{

fn database(&self) -> Option<Rc<DatabaseContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}
/// Retrieves all `TerminalNode`s corresponding to token PERIOD in current rule
fn PERIOD_all(&self) -> Vec<Rc<TerminalNode<'input,PlSqlParserContextType>>>  where Self:Sized{
	self.children_of_type()
}
/// Retrieves 'i's TerminalNode corresponding to token PERIOD, starting from 0.
/// Returns `None` if number of children corresponding to token PERIOD is less or equal than `i`.
fn PERIOD(&self, i: usize) -> Option<Rc<TerminalNode<'input,PlSqlParserContextType>>> where Self:Sized{
	self.get_token(PlSqlParser_PERIOD, i)
}
fn domain_all(&self) ->  Vec<Rc<DomainContextAll<'input>>> where Self:Sized{
	self.children_of_type()
}
fn domain(&self, i: usize) -> Option<Rc<DomainContextAll<'input>>> where Self:Sized{
	self.child_of_type(i)
}
/// Retrieves first TerminalNode corresponding to token AT_SIGN
/// Returns `None` if there is no child corresponding to token AT_SIGN
fn AT_SIGN(&self) -> Option<Rc<TerminalNode<'input,PlSqlParserContextType>>> where Self:Sized{
	self.get_token(PlSqlParser_AT_SIGN, 0)
}
fn connection_qualifier(&self) -> Option<Rc<Connection_qualifierContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}

}

