//------------------- system_privilege ----------------
pub type System_privilegeContextAll<'input> = System_privilegeContext<'input>;


pub type System_privilegeContext<'input> = BaseParserRuleContext<'input,System_privilegeContextExt<'input>>;

#[derive(Clone)]
pub struct System_privilegeContextExt<'input>{
ph:PhantomData<&'input str>
}

impl<'input> PlSqlParserContext<'input> for System_privilegeContext<'input>{}

impl<'input,'a> Listenable<dyn PlSqlParserListener<'input> + 'a> for System_privilegeContext<'input>{
		fn enter(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_system_privilege(self);
			Ok(())
		}fn exit(&self,listener: &mut (dyn PlSqlParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_system_privilege(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input> CustomRuleContext<'input> for System_privilegeContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = PlSqlParserContextType;
	fn get_rule_index(&self) -> usize { RULE_system_privilege }
	//fn type_rule_index() -> usize where Self: Sized { RULE_system_privilege }
}
antlr4rust::tid!{System_privilegeContextExt<'a>}

impl<'input> System_privilegeContextExt<'input>{
	fn new(parent: Option<Rc<dyn PlSqlParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<System_privilegeContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,System_privilegeContextExt{

				ph:PhantomData
			}),
		)
	}
}

